import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import Bank
B = Bank('127.', 1193, own='cte_116.jsonl')
def H(code, d, q, right, wrong, e): return B.hand(code, d, q, right, wrong, e)

# ---- 819 Precision Metal Manufacturing III ----
H("819.d.1.A",3,"During a shift handoff at a job shop, a lead machinist explains in two clear sentences which fixture is loaded, which program is running and what to watch for. She is expressing ideas to others in a:","clear, concise and effective manner through speaking",["long, rambling manner","unclear manner","silent manner"],"Clear speech prevents mistakes.")
H("819.d.1.A",4,"When briefing a crew at the start of a run, the best approach is to:","state the key points briefly and check for questions",["mumble the details","skip the details","talk about unrelated topics"],"Concise briefings keep teams aligned.")
H("819.d.1.B",3,"An apprentice writes an e-mail that lists the part number, the issue and the action needed so the engineer can reply without a call. She is conveying:","written information that is easily understandable to others",["confusing notes","vague hints","unfinished sentences"],"Clear writing saves time.")
H("819.d.1.B",4,"A good written shift report for a CNC cell includes:","what was run, any problems and what the next shift must do",["only a joke","only the weather","only a signature"],"Useful handoff notes.")
H("819.d.1.C",3,"A new hire at a Texas fab shop arrives before the start of the shift, clocks in on time and keeps her work area ready. She is demonstrating:","acceptable work ethics in reporting for duty and performing assigned tasks",["casual lateness","poor planning","avoiding duties"],"Reliability is a core work ethic.")
H("819.d.1.C",4,"A worker who cannot make it to a scheduled shift should:","notify the supervisor as early as possible",["say nothing","blame a coworker","come in late without telling anyone"],"Early notice allows coverage.")
H("819.d.1.D",3,"A machinist keeps cell phone use for breaks, wears the required safety gear and speaks respectfully to visitors on the floor. She is conducting herself:","in a manner acceptable for the profession and work situation",["carelessly","rudely","impulsively"],"Professional conduct fits the job.")
H("819.d.1.D",4,"Which action best shows professional conduct around customers touring a shop?","using polite language and staying within safe walkways",["shouting across the floor","playing music loudly","leaving tools in the aisle"],"Respect and safety.")
H("819.d.1.E",3,"A technician discovers that the inspection form was filled in before the parts were measured and decides to report it and follow the quality procedure instead of going along. She is choosing:","the ethical course of action and complying with rules and regulations",["the easy course","the fastest course","the silent course"],"Ethics means honesty and compliance.")
H("819.d.1.E",4,"If an inspection result is out of tolerance, the ethical response is to:","record the actual measurement and report it",["change the number","hide the part","ship it anyway"],"Honest data protects customers.")
H("819.d.1.F",3,"A quality technician rechecks a gauge reading, compares the thread callout to the print and reads the notes for finish requirements before approving a lot. She is reviewing:","with a critical eye the fine, detailed aspects of both quantitative and qualitative information",["only the headline","only the cover page","only the color"],"Details matter in quality.")
H("819.d.1.F",4,"A measurement that gives a number, such as a diameter of 0.750 inch, is an example of:","quantitative information",["qualitative information","opinion only","a guess"],"Numbers are quantitative.")
H("819.d.1.G",3,"A team reviews three weeks of scrap reports and notices most rejects come from the same lathe on second shift, then traces it to a worn collet. They are evaluating systems and identifying:","causes, problems and patterns to recommend improvements",["only blame","only colors","only prices"],"Data reveals patterns.")
H("819.d.1.G",4,"After finding that a machine produces undersized parts every Monday, the best next step is to:","look for what changes on Monday and test that cause",["ignore the pattern","replace every machine","stop recording data"],"Investigate root causes.")
H("819.d.1.H",3,"A machinist reads the work instruction twice, asks the lead to explain one step aloud and follows the company safety policy to the letter. She is following:","written and oral instructions and adhering to established business policies",["only her own ideas","only rumors","only shortcuts"],"Follow instructions and policy.")
H("819.d.1.H",4,"If a written work instruction and a verbal request seem to conflict, the machinist should:","clarify with the supervisor before proceeding",["pick the one she likes","do both at once","ignore both"],"Clarify conflicts.")
H("819.d.1.I",3,"A worker lists the day's jobs by due date, blocks time for setup and inspection and checks off each one so the hot job ships first. He is prioritizing tasks and:","following schedules and working on goal-relevant activities",["avoiding schedules","working randomly","doing unrelated tasks"],"Prioritization meets deadlines.")
H("819.d.1.I",4,"A job due tomorrow and a job due next week are both waiting. The better priority is to:","start the job due tomorrow first",["start the job due next week","start neither","start the easiest"],"Earlier deadlines come first.")
H("819.d.2.A",3,"A student programs and turns a stepped shaft with a groove and a thread to a NIMS Level 1 print and inspects every feature. She is producing:","a detailed turning part such as the NIMS Level 1 turning project",["a poster","a paper model","a sculpture"],"NIMS-style turning project.")
H("819.d.2.A",4,"For a NIMS Level 1 turned part, the final step before submitting it is to:","inspect each feature against the print",["paint it","skip inspection","guess at sizes"],"Final inspection.")
H("819.d.2.B",3,"A student mills a plate with a pocket, a 4-hole pattern and a contoured edge for a NIMS Level 1 submission. She is producing:","a detailed milling part such as the NIMS Level 1 milling part",["a photo album","a sketchbook","a paper craft"],"NIMS-style milling project.")
H("819.d.2.B",4,"A pocket on a milled part is:","a recessed feature cut into the surface",["a raised pin","a through-hole thread","a flat sheet"],"Pockets are recesses.")
H("819.d.3.A",3,"An operator changes from a 3/8-inch drill to a 1/2-inch end mill by hand for one job and uses the automatic changer for the next. She is performing:","various types of tool changes",["lighting changes","scene changes","music changes"],"Tool changes can be manual or automatic.")
H("819.d.3.A",4,"The safest time to change a tool manually on a CNC machine is when:","the spindle is stopped and the machine is in a safe condition",["the spindle is turning","the part is cutting","the door is open and running"],"Safe state first.")
H("819.d.3.B",3,"A shop uses tool holders that clamp into the spindle in seconds and already carry a preset tool length. They are demonstrating:","quick change tooling used on CNC milling machines",["slow tooling","handmade tooling","glued tooling"],"Quick-change reduces setup time.")
H("819.d.3.B",4,"A main benefit of presetting tools in quick-change holders is that it:","shortens the time the machine sits idle during setup",["increases spindle load","increases the noise","adds more manual work"],"Less downtime.")
H("819.d.3.C",3,"At the end of a job, a student wipes each holder and returns every tool to its labeled spot in a cabinet so edges are not nicked. She is demonstrating:","appropriate tool storage",["haphazard storage","tossing tools aside","leaving tools out"],"Good storage protects edges.")
H("819.d.3.C",4,"Storing end mills loose in a drawer so they hit each other can cause:","chipped cutting edges",["sharper edges","better finishes","longer tool life"],"Contact damages edges.")
H("819.d.3.D",3,"A student opens the offset page on the control and types a length value for tool 3 so the machine knows where the tip sits relative to the part. She is demonstrating the proper use of:","tool offset registers",["clock settings","wall paint","menu lists"],"Offset registers hold tool data.")
H("819.d.3.D",4,"The tool offset registers on a CNC control store information about each tool, such as its:","length and diameter",["color","price","brand history"],"Registers hold geometry.")
H("819.d.3.E",3,"A technician lowers a tool until it just touches a gauge block and reads the Z position to find the tool's length compared with a reference. She is determining:","tool offset length",["a work schedule","a lunch break","a delivery time"],"Touch-off gives length offsets.")
H("819.d.3.E",4,"Compared with touching off every tool on the machine, using a presetter off the machine:","saves machine time",["adds machine time","adds noise","reduces accuracy always"],"Presetters work offline.")
H("819.d.3.F",3,"After measuring three tools, the student types each length and diameter into the correct register and double-checks the entries before running the first part. She is:","entering tool offsets for a setup",["entering a contest","entering a building","entering a race"],"Correct entries prevent crashes.")
H("819.d.3.F",4,"A wrong digit in a tool length offset can cause:","the tool to cut too deep or stop short of the part",["a quieter machine","a faster part","a cleaner floor"],"Offset errors cause crashes.")

H("819.d.4.A",3,"A job-shop apprentice confirms the safety door interlock works, keeps loose sleeves away from the spindle and checks that the bar feeder is secured before running the turning center. She is working:","with equipment found on and around a CNC lathe in a safe manner",["without any guards","with the interlock bypassed","carelessly"],"Lathe safety checks come before cycle start.")
H("819.d.4.A",4,"The safety door interlock on a CNC lathe is designed to:","stop the spindle or prevent starting when the door is open",["lock the part in place","increase the cutting speed","hold the coolant"],"Interlocks protect operators.")
H("819.d.4.B",3,"On a photo of a turning center, a student correctly labels the headstock, chuck, turret, tailstock and control panel and states what each does. She is naming and describing:","the primary components of a CNC lathe",["parts of a skateboard","parts of a kitchen","parts of a bicycle"],"Know the machine's components.")
H("819.d.4.B",4,"The chuck on a CNC lathe is used to:","grip and rotate the workpiece",["hold the coolant","display the program","store the tools"],"The chuck holds the part.")
H("819.d.4.C",3,"Every Monday morning an operator checks the spindle lube, the hydraulic oil level and the chip conveyor on the turning center and logs the results. She is doing:","preventative maintenance checks on a CNC lathe",["decorating","scheduling lunch","sweeping the parking lot"],"PM checks prevent breakdowns.")
H("819.d.4.C",4,"Logging preventative maintenance checks is useful because it:","shows when service is due and tracks problems over time",["adds paperwork only","hides problems","replaces inspections"],"Records support maintenance.")
H("819.d.4.D",3,"With a handheld meter, a technician measures the percentage of concentrate in the coolant sump on the lathe and mixes in more concentrate when it reads low. She is testing the coolant for:","proper density and adjusting it to protect parts and tools",["flavor","color only","price"],"Right concentration protects parts.")
H("819.d.4.D",4,"Coolant mixed too lean on a CNC lathe is likely to:","allow rust and shorten tool life",["improve the finish","extend tool life","stop all heat"],"Weak coolant under-protects.")
H("819.d.4.E",3,"A student flips the main disconnect, waits for the control screen, clears any start-up alarms and sends the axes home before a first cut. She is performing:","a power up on a standard CNC lathe",["a power down","a data backup","a tool change"],"Follow the start-up sequence.")
H("819.d.4.E",4,"Power-up and homing on a CNC lathe is important because it:","sets a known reference position for the axes",["cools the spindle","loads the program","cleans the chips"],"Homing defines machine zero.")
H("819.d.4.F",3,"Using the pendant, a student moves the X and Z axes in small steps with the handwheel until the tool tip is a few thousandths from the bar face. She is demonstrating:","the use of the jog controls on the operator panel",["skipping the setup","running the program","cutting at full speed"],"Jogging positions axes manually.")
H("819.d.4.F",4,"The best jog setting when the tool is near the workpiece is:","the smallest increment or slowest speed",["maximum rapid","no limit","random"],"Small steps prevent crashes.")
H("819.d.4.G",3,"A student seats an insert in a tool holder, torques the screw and measures the overhang with a gauge before loading it into the lathe. She is demonstrating the ability to:","locate, assemble and measure tooling according to a setup sheet",["guess at tooling","ignore the setup sheet","skip measuring"],"Tooling follows the setup sheet.")
H("819.d.4.G",4,"A setup sheet for a CNC lathe typically lists:","each tool, its position and its offset information",["the weather","the workers' names","the lunch menu"],"Setup sheets organize tooling.")
H("819.d.4.H",3,"Following the setup sheet, a student places tool 1 in turret position 1, tool 2 in position 2 and tool 3 in position 3 and tightens each holder. She is:","installing tools and tool holders in the automatic tool changer locations",["removing the turret","painting the holders","skipping the sheet"],"Tool positions must match the program.")
H("819.d.4.H",4,"If tool numbers in the turret do not match the program, the likely outcome is:","the wrong tool will run, which can ruin the part or crash",["a quieter machine","a cleaner part","faster cycle time"],"Mismatch is dangerous.")
H("819.d.4.I",3,"With a bar in the chuck, the student faces the end lightly, retracts, reads the Z coordinate and tells the control that this is part zero. She is:","locating and setting the workpiece to zero on a CNC lathe",["resetting the clock","clearing the screen","cleaning the chuck"],"Z zero is set at the part face.")
H("819.d.4.I",4,"Setting a part zero lets the program:","reference the part rather than the machine's home",["ignore the part","run faster","use less power"],"Zero links the program to the part.")
H("819.d.4.J",3,"After touching off the stock, the student types the Z value into the G54 register so the program starts from the part face. She is setting:","any required work offsets for the part to be machined after a basic setup",["a new password","the time zone","a new tool"],"Work offsets reference part zero.")
H("819.d.4.J",4,"Which code commonly calls up the first stored work offset on a CNC control?","G54",["M30","T0101","S1200"],"G54 is the first work offset.")
H("819.d.4.K",3,"For each tool in the turret, the student enters X and Z geometry values and a nose radius so the control can place the cutting edge correctly. She is setting:","the proper geometry/tool offsets for each tool in a standard tool turret",["a clock","a theme","a ringtone"],"Geometry offsets locate each tool.")
H("819.d.4.K",4,"If the X geometry offset for a turning tool is wrong by 0.010 inch, the finished diameter will be:","off by about the same amount",["unchanged","perfect","twice as accurate"],"Offsets move the cutting position.")
H("819.d.4.L",3,"After the first piece passes inspection, the operator runs the next ten parts in automatic mode while watching the load meter and chip flow. She is:","operating a CNC lathe in automatic mode",["editing a program","calibrating the meter","cleaning the machine"],"Automatic mode runs the cycle.")
H("819.d.4.L",4,"While a lathe runs in automatic mode, the operator should be ready to:","press feed hold or emergency stop if something looks wrong",["leave the area","open the door","ignore alarms"],"Stay alert and ready.")
H("819.d.4.M",3,"At the end of the day, the operator moves the turret to its safe position, cleans out the chips, switches off the control and then the main power. She is illustrating:","the proper power down process on a CNC lathe",["a start-up","a program edit","a tool change"],"Shut down in order.")
H("819.d.4.M",4,"Chips should be cleared from a CNC lathe at the end of the shift to:","prevent damage and keep the machine accurate and safe",["slow the next shift","add noise","hide wear"],"Clean machines run better.")
H("819.d.5.A",3,"Before running a vertical machining center, a student checks that the vise jaws are snug, the guard door shuts and nothing is left on the table. She is working:","with equipment found on and around a CNC mill in a safe manner",["with the door open","with the guard removed","without checking"],"CNC mill safety checks.")
H("819.d.5.A",4,"Which of the following should be removed from a mill's table before running?","tools, wrenches and loose items",["the vise","the workpiece","the clamps in use"],"Loose items can become projectiles.")
H("819.d.5.B",3,"A student labels the spindle, column, saddle, table and control on a photo of a vertical machining center and states what each does. She is naming and describing:","the primary components of a CNC mill",["parts of a skateboard","parts of a refrigerator","parts of a piano"],"Know the machine's components.")
H("819.d.5.B",4,"On a vertical mill, the table moves the workpiece in:","X and Y directions",["spindle speed only","no directions","tool changes only"],"The table moves in X and Y.")
H("819.d.5.C",3,"On Fridays an operator checks the way-lube reservoir, cleans the spindle taper and inspects the air filter on the machining center. She is performing:","preventative maintenance checks on a CNC mill",["a safety quiz","a tool storage check","a program edit"],"Regular PM maintains accuracy.")
H("819.d.5.C",4,"Debris on a spindle taper can cause:","poor tool seating and runout",["better accuracy","less wear","longer tool life"],"Clean tapers seat tools.")
H("819.d.5.D",3,"A technician pulls a sample from the mill's coolant tank, reads the concentration on a refractometer and tops up with the right mix. She is testing the coolant for:","proper density and adjusting it",["a taste","a color match","a smell"],"Check concentration regularly.")
H("819.d.5.D",4,"Too-rich coolant mixed on a mill can leave:","a sticky residue and cause skin irritation",["no residue","a better finish always","less foam always"],"Over-concentration has downsides.")
H("819.d.5.E",3,"An operator turns the main disconnect on, waits for the control to boot, clears the alarms and presses the reference return button for every axis. She is performing:","a power up on a standard CNC mill",["a shutdown","a program edit","a tool setup"],"Start-up sequence.")
H("819.d.5.E",4,"On start-up, a CNC mill needs to be homed so that:","the control knows where each axis is",["the coolant turns on","the spindle speeds up","the tools are cleaned"],"Homing establishes a reference.")
H("819.d.5.F",3,"With the pendant, a student spins the handwheel one click at a time to bring the cutter edge down toward the part surface. She is demonstrating:","the use of the jog controls on the operator panel of a CNC mill",["running a program","editing code","changing a tool"],"Jogging moves axes by hand.")
H("819.d.5.F",4,"When jogging a mill's Z axis close to the part, the safest approach is to:","use a small handwheel increment while watching the tool",["jog quickly","look away","use rapid mode"],"Go slowly near the work.")
H("819.d.5.G",3,"A student tightens an end mill in a collet, sets the stickout to match the setup sheet and measures the assembled tool before loading it. She is demonstrating the ability to:","locate, assemble and measure tooling using a setup sheet",["ignore the sheet","guess the length","skip measuring"],"Follow the setup sheet.")
H("819.d.5.G",4,"A longer stickout on an end mill generally:","reduces rigidity and can cause chatter",["increases rigidity","improves finish","reduces vibration"],"Overhang reduces stiffness.")
H("819.d.5.H",3,"The student loads the face mill into pocket 1 of the tool carousel, the drill into pocket 2 and the end mill into pocket 3 as shown on the setup sheet. She is:","installing tools and tool holders in the automatic tool changer locations",["removing the carousel","painting the holders","guessing at pockets"],"Pocket positions match the program.")
H("819.d.5.H",4,"A tool called as T2 in a mill program must be located in:","tool pocket 2 of the changer",["pocket 5","the vise","the coolant tank"],"T numbers match pockets.")
H("819.d.5.I",3,"A student brings an edge finder against the left and front sides of the stock and records those machine positions as the part's X and Y zero. She is:","locating and setting the workpiece to zero on a CNC mill",["resetting a timer","resetting a password","resetting a tool"],"Edge finding sets zero.")
H("819.d.5.I",4,"The Z zero on a mill part is often set at:","the top surface of the stock",["the bottom of the vise","the machine ceiling","the tool changer"],"Top of stock is common.")
H("819.d.5.J",3,"After finding the stock edges and top, the student types the X, Y and Z positions into the G55 register for the second fixture. She is setting:","any required work offsets for the part to be machined after a basic setup",["a new password","a screen saver","a new date"],"Work offsets locate each fixture.")
H("819.d.5.J",4,"Using several work offsets such as G54 and G55 allows a mill to:","machine more than one part or fixture in a single program",["skip the setup","run without tools","ignore the print"],"Multiple offsets support multiple fixtures.")
H("819.d.5.K",3,"The student enters each cutter's length and diameter in the tool table so the control can place the tip correctly and apply compensation. She is setting:","the proper geometry/tool offsets for each tool in a standard tool changer",["a ringtone","a theme","a clock"],"Geometry offsets are per tool.")
H("819.d.5.K",4,"If a cutter's diameter offset is entered too small, a profile cut will leave:","extra material on the part",["too little material","a perfect size","a bigger hole"],"Under-compensation leaves stock.")
H("819.d.5.L",3,"After the first part passes inspection, the operator closes the door and lets the mill machine the batch hands-free while she monitors the screen. She is:","operating a CNC mill in automatic mode",["editing code","resetting offsets","cleaning the vise"],"Automatic mode runs production.")
H("819.d.5.L",4,"When a CNC mill makes an unusual noise during an automatic cycle, the operator should:","press feed hold or emergency stop and investigate",["ignore it","increase the speed","open the door during the cut"],"Stop and investigate abnormal sounds.")
H("819.d.5.M",3,"At day's end, the operator moves the table to a safe position, cleans out the chips and powers off the control before turning off the main disconnect. She is illustrating:","the proper power down process on a CNC mill",["a power up","a program edit","a tool change"],"Shutdown order matters.")
H("819.d.5.M",4,"Cleaning chips off a mill's table and ways at shutdown helps to:","protect the machine and prepare it for the next shift",["slow production","add noise","hide mistakes"],"Clean machines stay accurate.")

H("819.d.6.A",3,"A programmer reads a print of a tapered pin, finds the taper angle and uses the tangent function to calculate the change in diameter over a given length so she can enter the end points. She is using:","trigonometry to determine coordinates from technical drawings to create a lathe program",["a coin flip","a map","a hunch"],"Trig finds missing end points.")
H("819.d.6.A",4,"A right triangle has a 30-degree angle and a hypotenuse of 2 inches. The side opposite the 30-degree angle measures:","1 inch",["2 inches","0.5 inch","1.5 inches"],"sin 30° = 0.5; 2 × 0.5 = 1.")
H("819.d.6.B",3,"A programmer works out how far to shift a finishing path for a round insert so the turned taper lands on the print size. She is using:","trigonometry for determining cutter offsets",["art","chance","a tape measure only"],"Offsets use trig for angled surfaces.")
H("819.d.6.B",4,"Nose radius compensation on a lathe is needed most when cutting:","tapers and arcs",["straight faces only","straight diameters only","nothing"],"The tip radius affects angled cuts.")
H("819.d.6.C",3,"A programmer calculates the RPM needed for a 2-inch diameter at 300 surface feet per minute and sets the feed per revolution from the insert's chip load. She is using:","appropriate mathematical skills to solve problems while programming a turning center",["no math at all","only a hunch","only memory"],"Math supports every programming decision.")
H("819.d.6.C",4,"On a lathe, surface speed is the speed at which:","the material passes the cutting edge",["the coolant flows","the turret moves","the chips fall"],"Surface speed relates RPM and diameter.")
H("819.d.6.D",3,"A student writes a short program that turns the end of a bar flat and then cuts the outside to a 1.25-inch diameter for 3 inches. She is writing:","a simple program to face and turn",["a poem","a story","a report"],"Face-and-turn is a basic program.")
H("819.d.6.D",4,"In a basic turning program, the program usually ends with:","an M-code that stops the program and returns to the start",["a recipe","a comment only","nothing"],"M30 or M02 ends the program.")
H("819.d.6.E",3,"A student programs a 0.125-inch corner radius, a 15-degree taper, a groove for an O-ring and a 3/8-16 thread on the same shaft. She is writing:","a simple program to cut radiuses, angles, grooves and threads",["a song","a menu","a letter"],"Contours, grooves and threads add complexity.")
H("819.d.6.E",4,"A groove for an O-ring is cut with:","a grooving tool plunged straight into the part",["a drill","a reamer","a tap"],"Grooving tools cut grooves.")
H("819.d.6.F",3,"A programmer turns on tool nose compensation with G42 so the control offsets the path to the right of the programmed profile by the tip radius. She is writing:","a program using cutter radius compensation",["a program without offsets","a printed report","a recipe"],"Compensation keeps profiles accurate.")
H("819.d.6.F",4,"A G40 command in a CNC program:","cancels tool or cutter radius compensation",["turns on the coolant","changes the tool","starts the spindle"],"G40 cancels compensation.")
H("819.d.6.G",3,"Rather than programming each roughing pass separately, a programmer uses G71 with a start line, an end line and a depth of cut to remove stock from a shaft. She is writing:","a program using canned cycles such as G71",["a random sequence","a list of sizes","a shopping list"],"Canned cycles condense repetitive moves.")
H("819.d.6.G",4,"A main advantage of a canned cycle like G71 is that it:","makes the program shorter and easier to edit",["adds more lines","hides the toolpath","removes the need for a print"],"Fewer lines, easier edits.")
H("819.d.6.H",3,"A student writes a complete program for a NIMS Level 1 turned part that has faces, diameters, a radius, a groove and a thread and then cuts it. She is writing:","a program and producing a complex part such as a NIMS Level 1 CNC turning project",["a sketch","a note","a drawing"],"Complete project from print to part.")
H("819.d.6.H",4,"Before cutting the first complex part, the student should:","simulate the program and check each tool path",["skip simulation","run it at full speed blindly","remove the guard"],"Simulation catches errors.")
H("819.d.7.A",3,"A programmer applies sine and cosine to find the X and Y positions of six holes on a bolt circle from a print. She is using:","trigonometry to determine coordinates from technical drawings to create a mill program",["a game","a map","a guess"],"Trig finds hole positions.")
H("819.d.7.A",4,"For four equally spaced holes on a bolt circle, the angle between neighboring holes is:","90 degrees",["60 degrees","45 degrees","120 degrees"],"360 ÷ 4 = 90.")
H("819.d.7.B",3,"A programmer uses trigonometry to work out how far a 1/2-inch cutter must be offset from a 45-degree wall so the finished surface is on size. She is using:","trigonometry to determine cutter offsets",["art","chance","a tape measure only"],"Offsets for angled walls use trig.")
H("819.d.7.B",4,"For an end mill cutting a straight wall, the cutter's center path is offset from the wall by:","the cutter's radius",["the cutter's length","the wall's thickness","zero"],"Center is one radius away.")
H("819.d.7.C",3,"A programmer works out that a 1/2-inch, 3-flute end mill at 4,000 RPM with a 0.003-inch chip load needs a particular feed rate and enters it in the program. She is using:","appropriate mathematical skills to solve problems while programming a machining center",["only memory","no math","a coin toss"],"Feed rate is calculated.")
H("819.d.7.C",4,"For a 3-flute end mill at 4,000 RPM and a 0.003-inch chip load, the feed rate in inches per minute is:","36",["12","24","48"],"4000 × 0.003 × 3 = 36.")
H("819.d.7.D",3,"A student writes a program that center drills, drills and taps six holes using a drilling cycle and a hole pattern. She is writing:","a simple program to perform hole operations",["a speech","a story","a quiz"],"Hole operations use cycles.")
H("819.d.7.D",4,"A canned drilling cycle such as G83 is used to:","peck drill deep holes to clear chips",["tap threads only","face the part","change tools"],"Peck cycles clear chips.")
H("819.d.7.E",3,"A student programs the profile of a plate with a 0.5-inch corner radius and a 20-degree chamfer on one edge. She is writing:","a simple program to cut radiuses and angles",["a menu","a poem","a recipe"],"Contour programs include arcs and angles.")
H("819.d.7.E",4,"To cut a clockwise arc on a CNC mill, a programmer uses:","G02",["G00","G54","M03"],"G02 is clockwise circular interpolation.")
